@msig trait EvidenceLifecycle_coordination_evidence_lifecycle_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle)
  }

  /** helper function to set the values of all input ports.
   * @param imageFacts payload for data port imageFacts
   * @param contextFacts payload for data port contextFacts
   * @param recoveryFrame payload for data port recoveryFrame
   */
  def put_concrete_inputs(imageFacts : EIT_Image_Availability_Coordinator.ImageFacts.Type,
                          contextFacts : EIT_Image_Availability_Coordinator.ContextFacts.Type,
                          recoveryFrame : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    put_imageFacts(imageFacts)
    put_contextFacts(contextFacts)
    put_recoveryFrame(recoveryFrame)
  }


  /** helper function to check EvidenceLifecycle_coordination_evidence_lifecycle's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param evidenceFrame method that will be called with the value of the outgoing data
   *        port 'evidenceFrame'.
   */
  def check_concrete_output(evidenceFrame: EIT_Image_Availability_Coordinator.EvidenceFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val evidenceFrameValue: EIT_Image_Availability_Coordinator.EvidenceFrame = get_evidenceFrame().get
    if(!evidenceFrame(evidenceFrameValue)) {
      testFailures = testFailures :+ st"'evidenceFrame' did not match expected: value of the outgoing data port is ${evidenceFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_imageFacts(value : EIT_Image_Availability_Coordinator.ImageFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle.operational_api.imageFacts_Id, EIT_Image_Availability_Coordinator.ImageFacts_Payload(value))
  }

  // setter for in DataPort
  def put_contextFacts(value : EIT_Image_Availability_Coordinator.ContextFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle.operational_api.contextFacts_Id, EIT_Image_Availability_Coordinator.ContextFacts_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryFrame(value : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle.operational_api.recoveryFrame_Id, EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(value))
  }

  // getter for out DataPort
  def get_evidenceFrame(): Option[EIT_Image_Availability_Coordinator.EvidenceFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.EvidenceFrame] = get_evidenceFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.EvidenceFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port evidenceFrame.  Expecting 'EIT_Image_Availability_Coordinator.EvidenceFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.EvidenceFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_evidenceFrame_payload(): Option[EIT_Image_Availability_Coordinator.EvidenceFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_evidence_lifecycle.initialization_api.evidenceFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.EvidenceFrame_Payload]]
  }

}
